	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	membership, exists := r.memberships[id]
	if !exists {
		return domain.ErrNotFound
	}
	delete(r.memberships, id)
	delete(r.pairIndex, membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID})
	return nil
}
